&lt;li&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Pryor&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Elk City&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Woodward&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;strong&gt;Join the VitalCaring team for a one-day hiring event focused on connecting passionate healthcare professionals with meaningful careers in Home Health!&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
